        val result = io.xberg.android.HtmlToMarkdown.convert("<table><thead><tr><th>Expression</th><th>Result</th></tr></thead><tbody><tr><td>a | b</td><td>true</td></tr></tbody></table>", null)
        assertTrue(result.content != null, "expected non-empty value")
        assertTrue(result.content.orEmpty().contains("Expression"), "expected to contain: " + "Expression")
        assertTrue(result.content.orEmpty().contains("Result"), "expected to contain: " + "Result")
        assertTrue(result.content.orEmpty().contains("true"), "expected to contain: " + "true")
    }

    @Test
    fun testTableRaggedRowFewerCellsThanHeader(): Unit = runBlocking {
        // A data row with fewer cells than the header is padded to the declared column count
        val result = io.xberg.android.HtmlToMarkdown.convert("<table><tr><th>A</th><th>B</th><th>C</th></tr><tr><td>1</td><td>2</td></tr></table>", null)
        assertEquals("| A | B | C |\n| --- | --- | --- |\n| 1 | 2 |   |\n", result.content.orEmpty())
    }

    @Test
    fun testTableRaggedRowMoreCellsThanHeader(): Unit = runBlocking {
        // A data row with more cells than the header widens the separator so no cell is silently dropped
        val result = io.xberg.android.HtmlToMarkdown.convert("<table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td><td>3</td></tr></table>", null)
        assertEquals("| A | B |   |\n| --- | --- | --- |\n| 1 | 2 | 3 |\n", result.content.orEmpty())
    }

    @Test
    fun testTableRaggedRowsPaddedNotListed(): Unit = runBlocking {
        // A headerless table whose rows have different cell counts is padded, not turned into a list
        val result = io.xberg.android.HtmlToMarkdown.convert("<table><tr><td>A</td><td>B</td></tr><tr><td>C</td></tr></table>", null)
        assertEquals("| A | B |\n| --- | --- |\n| C |   |\n", result.content.orEmpty())
    }

    @Test
    fun testTableWithAlignment(): Unit = runBlocking {
        // Table with column alignment attributes
        val result = io.xberg.android.HtmlToMarkdown.convert("<table><thead><tr><th align=\"left\">Left</th><th align=\"center\">Center</th><th align=\"right\">Right</th></tr></thead><tbody><tr><td>L</td><td>C</td><td>R</td></tr></tbody></table>", null)
        assertTrue(result.content != null, "expected non-empty value")
        assertTrue(result.content.orEmpty().contains("Left"), "expected to contain: " + "Left")
        assertTrue(result.content.orEmpty().contains("Center"), "expected to contain: " + "Center")
        assertTrue(result.content.orEmpty().contains("Right"), "expected to contain: " + "Right")
        assertTrue(result.content.orEmpty().contains("L"), "expected to contain: " + "L")
        assertTrue(result.content.orEmpty().contains("C"), "expected to contain: " + "C")
        assertTrue(result.content.orEmpty().contains("R"), "expected to contain: " + "R")
        assertTrue(result.content.orEmpty().contains("|"), "expected to contain: " + "|")
    }

    @Test
    fun testTableWithColspan(): Unit = runBlocking {
        // Table with colspan attribute in a header cell
        val result = io.xberg.android.HtmlToMarkdown.convert("<table><thead><tr><th colspan=\"2\">Full Name</th></tr></thead><tbody><tr><td>John</td><td>Doe</td></tr></tbody></table>", null)
        assertTrue(result.content != null, "expected non-empty value")
        assertTrue(result.content.orEmpty().contains("Full Name"), "expected to contain: " + "Full Name")
        assertTrue(result.content.orEmpty().contains("John"), "expected to contain: " + "John")
        assertTrue(result.content.orEmpty().contains("Doe"), "expected to contain: " + "Doe")
    }

    @Test
    fun testTaggedSpaceInStrikethroughKept(): Unit = runBlocking {
        // A whitespace-only strikethrough keeps the word separator
        val result = io.xberg.android.HtmlToMarkdown.convert("<p>A<del> </del>B</p>", null)
        assertEquals("A B\n", result.content.orEmpty())
    }

    @Test
    fun testTaggedSpaceInSubscriptKept(): Unit = runBlocking {
        // A whitespace-only subscript keeps the word separator
        val result = io.xberg.android.HtmlToMarkdown.convert("<p>A<sub> </sub>B</p>", null)
        assertEquals("A B\n", result.content.orEmpty())
    }

    @Test
    fun testTaggedSpaceNotDuplicated(): Unit = runBlocking {
        // A whitespace-only inline element contributes exactly one space
        val result = io.xberg.android.HtmlToMarkdown.convert("<p>A<i> </i>B</p>", null)
        assertEquals("A B\n", result.content.orEmpty())
    }

    @Test
    fun testUnorderedList(): Unit = runBlocking {
        // Unordered list
        val result = io.xberg.android.HtmlToMarkdown.convert("<ul><li>Item 1</li><li>Item 2</li><li>Item 3</li></ul>", null)
        assertTrue(result.content.orEmpty().contains("- Item 1"), "expected to contain: " + "- Item 1")
        assertTrue(result.content.orEmpty().contains("- Item 2"), "expected to contain: " + "- Item 2")
        assertTrue(result.content.orEmpty().contains("- Item 3"), "expected to contain: " + "- Item 3")
    }

    @Test
    fun testWhitespaceOnlyBoldWrapperKeepsSeparator(): Unit = runBlocking {
        // A bold wrapper holding only a newline-only span still separates the words on either side
        val result = io.xberg.android.HtmlToMarkdown.convert("<b>Alpha</b><b><span>\n</span></b><b>Beta</b>", null)
        assertEquals("**Alpha** **Beta**\n", result.content.orEmpty())
    }

    @Test
    fun testWhitespaceOnlyCodeSpanKept(): Unit = runBlocking {
        // A code span whose content is a single space survives
        val result = io.xberg.android.HtmlToMarkdown.convert("<p>A<code> </code>B</p>", null)
        assertEquals("A` `B\n", result.content.orEmpty())
    }

